    assertValidTimeZone(timeZone);
    return true;
  } catch {
    return false;
  }
}

const formatters = new Map<string, Intl.DateTimeFormat>();

function formatterFor(timeZone: string): Intl.DateTimeFormat {
  const cached = formatters.get(timeZone);
  if (cached) return cached;
  const created = new Intl.DateTimeFormat("en-US", {
    timeZone,
    hourCycle: "h23",
    year: "numeric",
    month: "numeric",
    day: "numeric",
    hour: "numeric",
    minute: "numeric",
    second: "numeric",
  });
  formatters.set(timeZone, created);
  return created;
}

type WallClock = {
  year: number;
  month: number;
  day: number;
  hour: number;
};

function wallClock(ms: number, timeZone: string): WallClock {
  const parts = formatterFor(timeZone).formatToParts(new Date(ms));
  const pick = (type: string): number =>
    Number(parts.find((part) => part.type === type)?.value ?? "0");
  return {
    year: pick("year"),
    month: pick("month"),
    day: pick("day"),
    hour: pick("hour") % 24,
  };
}

/** The zone's wall clock at `ms`, read as if it were UTC. */
function wallMs(ms: number, timeZone: string): number {
  const parts = formatterFor(timeZone).formatToParts(new Date(ms));
  const pick = (type: string): number =>
    Number(parts.find((part) => part.type === type)?.value ?? "0");
  const subSecond = ((ms % 1000) + 1000) % 1000;
  const wall = new Date(0);
  wall.setUTCFullYear(pick("year"), pick("month") - 1, pick("day"));
  wall.setUTCHours(pick("hour") % 24, pick("minute"), pick("second"), subSecond);
  return wall.getTime();
}

function pseudoUtc(year: number, month: number, day: number, hour: number): number {
  const wall = new Date(0);
  wall.setUTCFullYear(year, month - 1, day);
  wall.setUTCHours(hour, 0, 0, 0);
  return wall.getTime();
}

/**
 * Every instant at which the zone's wall clock reads `wall` (a wall time
 * expressed as UTC ms), earliest first. Two instants when the clock is turned
 * back over it; when the clock is turned forward over it, the single instant
 * the skip happened.
 */
function instantsAt(wall: number, timeZone: string): number[] {
  const before = wallMs(wall - 36 * HOUR_MS, timeZone) - (wall - 36 * HOUR_MS);
  const after = wallMs(wall + 36 * HOUR_MS, timeZone) - (wall + 36 * HOUR_MS);

  const found = [...new Set([wall - before, wall - after])]
    .filter((instant) => wallMs(instant, timeZone) === wall)
    .sort((a, b) => a - b);
  if (found.length > 0) return found;

  // Inside a gap: the first instant whose wall clock is past `wall`.
  let lo = wall - Math.max(before, after);
  let hi = wall - Math.min(before, after);
  while (lo < hi) {
    const mid = Math.floor((lo + hi) / 2);
    if (wallMs(mid, timeZone) >= wall) hi = mid;
    else lo = mid + 1;
  }
