}

function parseLocalDate(date: string): { year: number; month: number; day: number } {
  const match = /^(\\d{4})-(\\d{2})-(\\d{2})$/.exec(date);
  if (!match) throw new RangeError(`Malformed local date: "${date}"`);
  return { year: Number(match[1]), month: Number(match[2]), day: Number(match[3]) };
}

function formatLocalDate(year: number, month: number, day: number): string {
  const y = String(year).padStart(4, "0");
  const m = String(month).padStart(2, "0");
  const d = String(day).padStart(2, "0");
  return `${y}-${m}-${d}`;
}

/** The `YYYY-MM-DD` calendar date of an instant on the zone's clock. */
export function localDate(value: IsoTimestamp, timeZone: string): string {
  const { year, month, day } = wallClock(parseIso(value).getTime(), timeZone);
  return formatLocalDate(year, month, day);
}

/** The hour (0-23) the zone's clock shows at `reference`. */
export function localHour(reference: Date, timeZone: string): number {
  return wallClock(reference.getTime(), timeZone).hour;
}

/** Moves a `YYYY-MM-DD` calendar date by whole days. */
export function shiftLocalDate(date: string, days: number): string {
  const { year, month, day } = parseLocalDate(date);
  const shifted = new Date(0);
  shifted.setUTCFullYear(year, month - 1, day + days);
